"""벨한다 설명(NOTE) 문구 — build_belhanda.py가 globals()를 넘겨 부름"""

def make_note(V):
    M, E, ST, CN = V["M"], V["E"], V["ST"], V["CN"]
    judg, SRC, SRC_A = V["judg"], V["ELO_SRC"], V["SRC_A"]
    def d_(s): y, m, d = s.split("-"); return f"{int(y)}.{int(m)}.{int(d)}"
    def c3(v): return f"{v[0]}·{v[1]}·{v[2]}"
    first, last = M[0], M[-1]
    pkx = [j for j in judg if j[0] == "도움 제외" and j[5] == "PK 유도"]
    unc = [j for j in judg if j[0] == "도움 제외(단일 출처 미확인)"]
    selfa = [j for j in judg if j[0].startswith("도움 아님")]
    man = sorted({(o, v[1], v[2]) for (o, d), v in V["ELO_LOG"].items() if v[0] == "man"})
    cnf = V["ADD_CONFIRMED"]
    L = [
        f"유네스 벨한다(몽펠리에 HSC·디나모 키이우·샬케 04·OGC 니스·갈라타사라이·아다나 데미르스포르·알샤말·알사일리야)의 클럽 공식 경기 {V['NG']}경기({d_(first[0])} {first[1]}전 ~ {d_(last[0])} {last[1]}전)에서 나온 {V['NGo']}골 {V['NA']}도움(PK 골 {V['NPK']}개), 친선경기·모로코 대표팀·몽펠리에 U19(2009 쿠프 감바르델라 결승) 제외",
        "클럽별 경기·골·도움: " + ", ".join(f"{CN[k]} {c3(v)}" for k, v in ST.items()) + f". 출전 분 합계 {V['MIN_TOT']:,}분",
        "출처: 경기 목록·출전 분은 Transfermarkt 선수 경기 성적, 골 시각·골 순서·PK·도움은 Transfermarkt 경기 리포트(골·도움이 있는 경기와 리그 밖 경기 전부, 리포트 골·도움 수가 선수 경기 성적과 경기마다 같음). 경기 수·골은 영어(아다나까지)·프랑스어 위키백과 클럽·시즌별 기록, FotMob 경력 합계와 같음(영어 위키백과 디나모 2013-14 합계 8골은 대회별 합 7골과 어긋나는 표기 오류, 프랑스어 위키백과 카타르 시즌 줄은 Transfermarkt와 1~4경기씩 다름). FotMob 경기 기록(2010-11부터)과 골 84경기를 대조해 골 수·PK가 모두 같음(분 차이 1~2분은 Transfermarkt 기준)",
        "모든 소속 팀-시즌이 1부 프로 리그(리그1·우크라이나 프리미어리그·분데스리가·쉬페르리그·카타르 스타스리그)",
        "출전 분: Transfermarkt 그대로(빈칸 없음, 90분 추정 없음). 연장 경기는 Transfermarkt 출전 분. 날짜는 경기 현지 날짜. 2010-11 쿠프 드 라 리그 8강 릴전(12분 출전)은 Transfermarkt가 2010.10.10로 적었으나 16강(10.26)보다 앞이라 맞지 않아 FotMob 경기 날짜 2010.11.10(수)을 씀(프랑스어 위키백과는 '11월 27일 수요일'로 적었는데 그날은 토요일)",
        f"골: 자책골·PK 리바운드 골 없음. PK 골 {V['NPK']}개는 Transfermarkt 골 유형 'Penalty'(FotMob과 같음)",
        f"도움: 2014년 8월 전은 Transfermarkt 리포트 단일 출처를 씀(클로제·니앙 선례). 2014년 8월 뒤는 Transfermarkt와 FotMob(경기 이벤트 {SRC_A['TM∩FotMob 경기 이벤트']}개 또는 선수 경기 목록의 경기별 도움 수 {SRC_A['TM∩FotMob 선수 경기 목록']}개)이 함께 센 것과, FotMob 자료가 없는 경기에서 다른 출처 2곳이 확인한 {len(cnf)}개만 넣음. Transfermarkt 도움 {V['N_TM_A']}개 − PK 유도 {len(pkx)}개(" + ", ".join(f"{d_(j[1])} {j[2]}전 {j[3]}분 {j[4]} PK" for j in pkx) + f") − 확인 못 한 단독 도움 {len(unc)}개 = {V['NA']}개. 유형 칸이 빈 Transfermarkt 도움은 2014년 8월 전 2개(일반 도움으로 셈)와 2024.3.11 알마르키야전 1개(확인 못 해 뺌). 본인 PK 골에 붙은 본인 도움 표기 {len(selfa)}개(2012.9.1 소쇼전 16분·2012.9.18 아스널전 9분)는 도움이 아님",
        "다른 출처 2곳으로 확인해 넣은 도움: " + "; ".join(cnf.values()),
        "확인 못 해 뺀 단독 도움: " + "; ".join(j[5] for j in unc) + ". 카타르 경기(2024~2025)는 FotMob 경기 기록에 도움·라인업이 없고, 리그 공식 기사·카타르 신문·통신 기사에서 도움자를 2곳 이상 찾지 못해 뺐으므로 실제 도움보다 적을 수 있음. 2025-26 알샤말·알사일리야와 2026-27 경기는 FotMob 선수 경기 목록 도움 수가 Transfermarkt와 같아 넣음",
        "몰수 경기: 벨한다가 뛴 경기 중 공식 판정으로 결과가 바뀐 경기는 없음. 아다나 2022-23 하타이스포르·가지안테프전 3-0 판정승(지진으로 두 팀 기권)은 출전 없음. 2025-26 카타르 스타스리그 17라운드 카타르 SC–알샤말 몰수 판정(알샤말 3-0)은 벨한다가 알사일리야로 옮긴 뒤 경기라 해당 없음",
        f"상대 Elo는 같은 경기를 다룬 다른 선수 자료(카벨라·사네·고미스·팔카오·투란 등), 같은 팀·같은 시즌 다른 선수 자료 값, 직접 추정, 그 시즌 최종 순위(Transfermarkt 순위표)를 기존 리그 순위값·리그 모형에 넣은 값 순으로 씀(기록 {len(E)}개: 같은 경기 {SRC['같은 경기 다른 선수 자료']}, 같은 팀·시즌 {SRC['기존 팀×시즌 값']}, 순위표+모형 {SRC['순위표+리그 모형']}, 직접 {SRC['직접 추정']})",
        "리그 모형(추정 표시): 우크라이나 1부는 셰브첸코·고메스 자료와 같은 국가 계수 회귀(리그 평균 = 1473 + 23.33 × (앞뒤 3시즌 UEFA 국가 계수 평균 − 7.333) − 73, 흩어짐 119; 계수 2012-13 9.500·2013-14 7.833·2014-15 10.000·2015-16 9.800·2016-17 5.500, kassiesa.net), 쉬페르리그는 같은 시즌 기존 순위값, 빈 순위는 앞뒤 값 사이 직선 값, 끝 순위는 튀르키예 리그 수준 회귀(투란·팔카오 자료와 같은 공식), 튀르키예 2·3부는 쉬페르리그 평균 − 162·− 324, 카타르 스타스리그는 마레즈·루이스 알베르토 자료와 같은 순위값(2025-26은 공식 최종 순위: 몰수 판정 반영으로 카타르 SC 6위·알아라비 7위·알와크라 8위, 2026-27은 11월 18일 현재 순위), 리그2(2부)는 평균 1540 모형",
        "직접 추정(모두 '추정'): " + ", ".join(f"{o} {e}({lv})" for o, e, lv in man),
        "대회 비중: 쿠프 드 프랑스·쿠프 드 라 리그·우크라이나컵·튀르키예컵·카타르 에미르컵·QSL컵은 국내컵(16강까지 낮은 비중, 8강 이후 높은 비중), QSL컵 조별은 리그식(무승부 1점), 우크라이나·튀르키예 슈퍼컵은 국내컵 결승. 챔스 조별, 유로파 예선·조별, 유로파 32강·8강은 유로파 토너먼트, 컨퍼런스 예선 2·3라운드·플레이오프는 컨퍼런스 예선",
        f"두 경기 합산 기록 {V['NTIE']}개({V['NTIEG']}경기)는 합산 S로 계산함: UEFA 대회 2020-21까지·튀르키예컵 2020-21까지·우크라이나컵(2014-15 대회 문서의 원정 다득점·연장 진출 사례)은 원정 다득점·연장, 2023-24 컨퍼런스 예선은 원정 다득점 없이 연장. 다른 차전 스코어는 Transfermarkt 리포트",
        "시즌 구분: 몽펠리에·디나모 키이우·아다나는 7월 10일 기준(2010.7.29 유로파 예선, 2013~2015 우크라이나 리그 7월 개막·2014.7.22 슈퍼컵, 2023.7.27 컨퍼런스 예선이 새 시즌), 갈라타사라이는 7월 10일 기준이되 2020.7.1~8.31(코로나로 늦게 끝난 2019-20 쉬페르리그)은 2019-20(2017.7.20 유로파 예선 외스테르순드전은 2017-18), 샬케·니스·알샤말·알사일리야는 기본 8월 1일. 클럽 구분(Transfermarkt 이적 기록): 2013.7.1 디나모, 2016.1.6 샬케 임대, 2016.8.31 니스 임대, 2017.7.3 갈라타사라이, 2021.3 계약 해지 뒤 2021.7.1 아다나, 2024.1.26 알샤말, 2026.1.14 알사일리야. 경기 클럽과 경계 불일치 0",
        "같은 경기 동료 자료: 카벨라(몽펠리에, 벨한다 도움→카벨라 골 2개·카벨라 도움→벨한다 골 1개), 고미스(갈라타사라이, 벨한다 도움→고미스 골 5개·고미스 도움→벨한다 골 1개), 투란(벨한다 도움→투란 골 1개·투란 도움→벨한다 골 2개), 팔카오·사네 같은 경기 상대 값과 날짜·분·골 전 스코어·대회·상대 Elo·수준 설명이 모두 같음. 상대 팀 선수 자료(니앙·지울리·메네즈·구르퀴프·오바메양·루이스 알베르토·드락슬러 등)와 골 순서도 맞음",
        "수상 기록은 Transfermarkt 업적 페이지 기준: 리그1 2011-12(몽펠리에), 우크라이나 리그 2014-15·2015-16(2015-16은 전반기 출전), 우크라이나컵 2013-14·2014-15, 쉬페르리그 2017-18·2018-19, 튀르키예컵 2018-19, 튀르키예 슈퍼컵 2019. 선수협회(UNFP) 리그1 올해의 팀 2011-12(프랑스어 위키백과 'Trophées UNFP du football 2012' équipe type). UNFP 기량 발전·올해의 골·마르크비비앵 푀상, CAF 올해의 팀, 리그 준우승·슈퍼컵 준우승, 대표팀 기록은 뺌",
        f"마지막 갱신: 2026.11.18(마지막 반영 경기 {d_(last[0])} {last[1]}전, 카타르 스타스리그 9라운드, 알사일리야 소속 현역)",
    ]
    return "\n".join(L)
